INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-007', TRUE, '工学院', '2026-10-09', '关于公开招募机械与车辆工程学院办公室学生助理通知2026-10-09', '学工事务', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "为进一步加强学生管理工作，提升学生综合素质，促进学生全面发展，为广大同学提供一个锻炼自己、展现自己的", "quote": "为进一步加强学生管理工作，提升学生综合素质，促进学生全面发展，为广大同学提供一个锻炼自己、展现自己的"}]'::jsonb, '学工事务：关于公开招募机械与车辆工程学院办公室学生助理通知2026-10-09', '[{"text": "为进一步加强学生管理工作，提升学生综合素质，促进学生全面发展，为广大同学提供一个锻炼自己、展现自己的", "quote": "为进一步加强学生管理工作，提升学生综合素质，促进学生全面发展，为广大同学提供一个锻炼自己、展现自己的"}]'::jsonb, '为进一步加强学生管理工作，提升学生综合素质，促进学生全面发展，为广大同学提供一个锻炼自己、展现自己的平台，经学院研究决定，现面向全院本科阶段学生招募学生助理。将有关事项通知如下： 一、招募对象 机械与车辆工程学院本科阶段以 2025级、2026级本科学生为主，其他年级学生也可参加。 二、招募条件 1、坚持四项基本原则，拥护国家方针政策，遵纪守法，具有较高的思想政治素质及道德素养； 2、为人踏实认真，工作、学习时细致有耐心，工作态度端正，责任心强； 3、善于沟通协调，有敏锐的观察力、较强的执行力和组织协调能力； 4、', 'https://gxy.ahau.edu.cn/info/1143/43721.htm', '工学院 · 通知公告', 'gxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at